-- The cases of test_run_sql_window_frames: each COPY line below is one case,
-- the query DuckDB runs over frames.parquet or edge.parquet (data.sql) and
-- the file its answer goes to. The test reads THIS FILE for the query text
-- and runs the same text through run_sql with each table name replaced by the
-- file's path, so a query has one source. A case's name is its output file
-- without `.tsv`. Every window column is aliased, its prefix naming its type
-- (n_ BIGINT, d_ DOUBLE, s_ VARCHAR), and each case is deterministic in
-- DuckDB: a ROWS frame orders by id, which has no tie, and a RANGE frame,
-- whose peers share a frame, reads values that do not depend on which peer
-- comes first (aggregates, and first_value or last_value of the key itself).
COPY (SELECT id, p, sum(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 2 PRECEDING AND 1 FOLLOWING) AS n_sum, count(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 2 PRECEDING AND 1 FOLLOWING) AS n_cnt, count(*) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 2 PRECEDING AND 1 FOLLOWING) AS n_star, avg(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 2 PRECEDING AND 1 FOLLOWING) AS d_avg, min(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 2 PRECEDING AND 1 FOLLOWING) AS n_min, max(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 2 PRECEDING AND 1 FOLLOWING) AS n_max, sum(x) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 2 PRECEDING AND 1 FOLLOWING) AS d_sum, min(x) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 2 PRECEDING AND 1 FOLLOWING) AS d_min, max(x) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 2 PRECEDING AND 1 FOLLOWING) AS d_max FROM read_parquet('frames.parquet')) TO 'rows_sliding.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, p, sum(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS n_sum, count(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 1 FOLLOWING AND 3 FOLLOWING) AS n_cnt, max(x) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 1 FOLLOWING AND 3 FOLLOWING) AS d_max, avg(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 5 PRECEDING AND 4 PRECEDING) AS d_avg, min(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 2 FOLLOWING AND UNBOUNDED FOLLOWING) AS n_min FROM read_parquet('frames.parquet')) TO 'rows_empty_edges.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, p, sum(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS n_run, min(x) OVER (PARTITION BY p ORDER BY id ROWS UNBOUNDED PRECEDING) AS d_run, sum(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) AS n_tail, max(v) OVER (PARTITION BY p ORDER BY id ROWS 3 PRECEDING) AS n_max3, count(*) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND 2 FOLLOWING) AS n_cnt FROM read_parquet('frames.parquet')) TO 'rows_running_and_tail.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, p, first_value(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 1 PRECEDING AND 2 FOLLOWING) AS n_first, last_value(t) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 1 PRECEDING AND 2 FOLLOWING) AS s_last, nth_value(v, 2) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS n_nth, first_value(t) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 1 FOLLOWING AND 2 FOLLOWING) AS s_first, last_value(x) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS d_last FROM read_parquet('frames.parquet')) TO 'rows_value_fns.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, p, sum(v) OVER (PARTITION BY p ORDER BY id DESC ROWS BETWEEN 1 PRECEDING AND 3 FOLLOWING) AS n_sum, first_value(v) OVER (PARTITION BY p ORDER BY id DESC ROWS BETWEEN 1 PRECEDING AND 3 FOLLOWING) AS n_first, count(*) OVER (PARTITION BY p ORDER BY id DESC ROWS BETWEEN 2 FOLLOWING AND 4 FOLLOWING) AS n_cnt FROM read_parquet('frames.parquet')) TO 'rows_desc.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, p, sum(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 9223372036854775807 PRECEDING AND 9223372036854775807 FOLLOWING) AS n_all, count(*) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 5000 FOLLOWING AND UNBOUNDED FOLLOWING) AS n_none, sum(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 0 PRECEDING AND 0 FOLLOWING) AS n_self FROM read_parquet('frames.parquet')) TO 'rows_wide_offsets.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, p, sum(v) OVER (PARTITION BY p ORDER BY k RANGE BETWEEN 2 PRECEDING AND 3 FOLLOWING) AS n_sum, count(*) OVER (PARTITION BY p ORDER BY k RANGE BETWEEN 2 PRECEDING AND 3 FOLLOWING) AS n_star, avg(v) OVER (PARTITION BY p ORDER BY k RANGE BETWEEN 2 PRECEDING AND 3 FOLLOWING) AS d_avg, min(x) OVER (PARTITION BY p ORDER BY k RANGE BETWEEN 2 PRECEDING AND 3 FOLLOWING) AS d_min, max(v) OVER (PARTITION BY p ORDER BY k RANGE BETWEEN 2 PRECEDING AND 3 FOLLOWING) AS n_max, first_value(k) OVER (PARTITION BY p ORDER BY k RANGE BETWEEN 2 PRECEDING AND 3 FOLLOWING) AS n_first, last_value(k) OVER (PARTITION BY p ORDER BY k RANGE BETWEEN 2 PRECEDING AND 3 FOLLOWING) AS n_last FROM read_parquet('frames.parquet')) TO 'range_bigint.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, p, sum(v) OVER (PARTITION BY p ORDER BY k RANGE BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS n_before, count(*) OVER (PARTITION BY p ORDER BY k RANGE BETWEEN 1 FOLLOWING AND UNBOUNDED FOLLOWING) AS n_after, sum(v) OVER (PARTITION BY p ORDER BY k RANGE BETWEEN 3 FOLLOWING AND 5 FOLLOWING) AS n_ahead, count(*) OVER (PARTITION BY p ORDER BY k RANGE BETWEEN 0 PRECEDING AND 0 FOLLOWING) AS n_peers, max(x) OVER (PARTITION BY p ORDER BY k RANGE BETWEEN 4 PRECEDING AND 2 PRECEDING) AS d_back FROM read_parquet('frames.parquet')) TO 'range_bigint_one_sided.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, p, sum(v) OVER (PARTITION BY p ORDER BY k DESC RANGE BETWEEN 5 PRECEDING AND CURRENT ROW) AS n_sum, count(*) OVER (PARTITION BY p ORDER BY k DESC RANGE BETWEEN CURRENT ROW AND 2 FOLLOWING) AS n_cnt, sum(x) OVER (PARTITION BY p ORDER BY k DESC RANGE BETWEEN 1 FOLLOWING AND UNBOUNDED FOLLOWING) AS d_sum FROM read_parquet('frames.parquet')) TO 'range_bigint_desc.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, p, sum(v) OVER (PARTITION BY p ORDER BY i RANGE BETWEEN 10 PRECEDING AND 10 FOLLOWING) AS n_sum, count(*) OVER (PARTITION BY p ORDER BY i RANGE BETWEEN 10 PRECEDING AND 10 FOLLOWING) AS n_star, min(v) OVER (PARTITION BY p ORDER BY i DESC RANGE BETWEEN 3 PRECEDING AND 1 FOLLOWING) AS n_min, count(*) OVER (PARTITION BY p ORDER BY i RANGE BETWEEN 3000000000 PRECEDING AND CURRENT ROW) AS n_wide FROM read_parquet('frames.parquet')) TO 'range_int32.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, p, sum(v) OVER (PARTITION BY p ORDER BY f RANGE BETWEEN 1 PRECEDING AND 1 FOLLOWING) AS n_sum, count(*) OVER (PARTITION BY p ORDER BY f RANGE BETWEEN 1 PRECEDING AND 1 FOLLOWING) AS n_star, max(x) OVER (PARTITION BY p ORDER BY f RANGE BETWEEN 1 PRECEDING AND 1 FOLLOWING) AS d_max, count(*) OVER (PARTITION BY p ORDER BY f RANGE BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS n_before, count(*) OVER (PARTITION BY p ORDER BY f DESC RANGE BETWEEN 2 PRECEDING AND CURRENT ROW) AS n_desc, count(*) OVER (PARTITION BY p ORDER BY f RANGE BETWEEN 0 PRECEDING AND 0 FOLLOWING) AS n_peers FROM read_parquet('frames.parquet')) TO 'range_double.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, sum(v) OVER (ORDER BY k RANGE BETWEEN 1 PRECEDING AND 1 FOLLOWING) AS n_sum, count(*) OVER (ORDER BY id ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) AS n_cnt FROM read_parquet('frames.parquet')) TO 'no_partition.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, p, row_number() OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS n_rn, rank() OVER (PARTITION BY p ORDER BY k RANGE BETWEEN 1 PRECEDING AND CURRENT ROW) AS n_rk, lag(v) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 1 FOLLOWING AND 2 FOLLOWING) AS n_lag FROM read_parquet('frames.parquet')) TO 'frame_ignored.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, p, sum(v) OVER (PARTITION BY p ORDER BY k RANGE BETWEEN 1 PRECEDING AND 1 FOLLOWING) AS n_sum, sum(x) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) AS d_sum FROM read_parquet('frames.parquet') WHERE v > 0 AND k IS NOT NULL) TO 'over_where.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, p, sum(v) OVER (PARTITION BY p ORDER BY k RANGE BETWEEN 1 PRECEDING AND 1 FOLLOWING) AS n_sum, count(*) OVER (PARTITION BY p ORDER BY id ROWS BETWEEN 1 FOLLOWING AND 2 FOLLOWING) AS n_cnt FROM read_parquet('frames.parquet') WHERE id < 0) TO 'no_row.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, sum(x) OVER (ORDER BY k RANGE BETWEEN 9223372036854775807 PRECEDING AND CURRENT ROW) AS n_sum, count(*) OVER (ORDER BY k DESC RANGE BETWEEN CURRENT ROW AND 9223372036854775807 FOLLOWING) AS n_cnt FROM read_parquet('edge.parquet') WHERE k > 0) TO 'edge_bigint_wide.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT id, count(*) OVER (ORDER BY i RANGE BETWEEN 3000000000 PRECEDING AND CURRENT ROW) AS n_lo, count(*) OVER (ORDER BY i RANGE BETWEEN CURRENT ROW AND 2147483648 FOLLOWING) AS n_hi, sum(x) OVER (ORDER BY i DESC RANGE BETWEEN 2147483648 PRECEDING AND 2147483648 FOLLOWING) AS n_all FROM read_parquet('edge.parquet')) TO 'edge_int32_wide.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
